package com.iumrah.beta.core.localization

/** Reviewed iOS language catalogues, verbatim. Generated from Swift byKey/byPhrase. */
internal object IumrahInternationalTranslations {
    fun byKey(code: String, value: String): String? = when (code) {
        "ar" -> arKey(value)
        "tr" -> trKey(value)
        "id" -> idKey(value)
        "ms" -> msKey(value)
        else -> null
    }
    fun byPhrase(code: String, value: String): String? = when (code) {
        "ar" -> arPhrase(value)
        "tr" -> trPhrase(value)
        "id" -> idPhrase(value)
        "ms" -> msPhrase(value)
        else -> null
    }
}

// Small chunks avoid the JVM 64 KB static initializer bytecode limit.
private fun arKey(value: String): String? = arKeyAll[value]
private val arKeyAll: Map<String, String> by lazy {
    buildMap {
        putAll(arKeyPart0.map)
        putAll(arKeyPart1.map)
        putAll(arKeyPart2.map)
        putAll(arKeyPart3.map)
        putAll(arKeyPart4.map)
        putAll(arKeyPart5.map)
        putAll(arKeyPart6.map)
    }
}
