        "The SMS service could not send the code right now. Please try again shortly." to "SMS hizmeti şu anda kod gönderemedi. Kısa süre sonra tekrar deneyin.",
        "The account was not found or the password is incorrect." to "Hesap bulunamadı veya şifre yanlış.",
        "The airline page could not be prepared." to "Havayolu sayfası hazırlanamadı.",
        "The booking and trip history remain available in iumrah." to "Rezervasyon ve yolculuk geçmişi iumrah'ta erişilebilir olmaya devam eder.",
        "The booking could not be deleted from the server. Nothing was removed from this iPhone." to "Rezervasyon sunucudan silinemedi. Bu iPhone'dan hiçbir şey kaldırılmadı.",
        "The booking holder has been confirmed. Your passport profile is securely linked to this trip and the booking is protected by Iumrah Security." to "Rezervasyon sahibi doğrulandı. Pasaport profiliniz bu seyahate güvenle bağlandı ve rezervasyon Iumrah Security tarafından koruma altına alındı.",
        "The booking was created without an access token. Please create a new booking or contact iumrah Care." to "Rezervasyon erişim anahtarı olmadan oluşturuldu. Yeni rezervasyon yapın veya iumrah Care ile iletişime geçin.",
        "The booking will be removed from your account only after the server confirms permanent deletion. This cannot be undone." to "Rezervasyon, ancak sunucu kalıcı silmeyi onayladıktan sonra hesabınızdan kaldırılır. Bu işlem geri alınamaz.",
        "The check is taking longer than usual" to "Kontrol normalden uzun sürüyor",
        "The code is valid for a limited time. Until it is confirmed, your current contact remains active." to "Kod sınırlı bir süre geçerlidir. Onaylanana kadar mevcut iletişim bilginiz etkin kalır.",
        "The code was sent by DevSMS and is valid for 10 minutes." to "Kod DevSMS ile gönderildi ve 10 dakika geçerlidir.",
        "The code was sent to your number and is valid for 10 minutes." to "Kod numaranıza gönderildi ve 10 dakika geçerlidir.",
        "The competent Saudi authority makes the final visa and admission decision." to "Vize verilmesine ve ülkeye girişe ilişkin nihai karar Suudi Arabistan'ın yetkili makamına aittir.",
        "The connection link is one-time and expires after 10 minutes. The bot receives access only to the booking you link." to "Bağlantı tek kullanımlıktır ve 10 dakika sonra geçerliliğini yitirir. Bot yalnızca bağladığınız rezervasyona erişebilir.",
        "The core journey is assembled automatically by the system. iumrah Care adds an extra layer of care when you want help balancing price, flights, hotel location or itinerary, so your focus can stay on Umrah and worship." to "Yolculuğun temel bileşenleri sistem tarafından otomatik olarak birleştirilir. Fiyat, uçuşlar, otel konumu veya güzergâhı dengelemek istediğinizde iumrah Care ek destek sunar; böylece siz Umre'ye ve ibadete odaklanabilirsiniz.",
        "The displayed difference is based on the complete journey fare for all selected travelers." to "Gösterilen fiyat farkı, seçilen tüm yolcuların toplam seyahat ücretine dayanır.",
        "The eSIM is intended for use during your Saudi Arabia journey." to "eSIM, Suudi Arabistan yolculuğunuz sırasında kullanılmak üzere sunulur.",
        "The email domain looks incomplete." to "E-posta alan adı eksik görünüyor.",
        "The entered details will be checked against the attached passport page before the security confirmation is completed." to "Güvenlik doğrulaması tamamlanmadan önce girdiğiniz bilgiler pasaport fotoğrafıyla karşılaştırılacaktır.",
        "The essentials before you contact Care." to "Care ile iletişime geçmeden önce bilmeniz gerekenler.",
        "The fare calendar grows from real searches and helps compare nearby dates before a new flight search is started." to "Fiyat takvimi gerçek aramalarla gelişir; yeni aramadan önce yakın tarihleri karşılaştırmanıza yardımcı olur.",
        "The feature is designed for pilgrims who booked through iumrah. The flight becomes part of one connected journey alongside hotels, transfer, Care and other services." to "Bu özellik, iumrah üzerinden rezervasyon yapan umre yolcuları için tasarlandı. Uçuş; oteller, transfer, Care ve diğer hizmetlerle birlikte tek bir yolculuğun parçası olur.",
        "The final price is visible in advance." to "Son fiyatı önceden görürsünüz.",
        "The flight provider took too long to respond." to "Uçuş sağlayıcısının yanıtı çok uzun sürdü.",
        "The flight system can no longer find the selected option %@." to "Uçuş sistemi seçilen %@ seçeneğini artık bulamıyor.",
        "The flights below were found by iumrah Scanner. Choose your outbound and return; the airfare is not shown separately and will be included in your personal package total." to "Aşağıdaki uçuşlar iumrah Scanner tarafından bulundu. Gidiş ve dönüşü seçin; bilet fiyatı ayrı gösterilmez, kişisel paket toplamınıza dahil edilir.",
        "The founder will personally review your trip once more." to "Kurucu seyahatinizi bir kez daha bizzat değerlendirecek.",
        "The goal is a calm digital companion before, during and after Umrah: planning, booking, status, guidance and human Care in one system." to "Amacımız, Umre öncesinde, sırasında ve sonrasında huzur veren dijital bir yol arkadaşı olmak: planlama, rezervasyon, durum takibi, rehberlik ve gerçek Care desteği tek sistemde.",
        "The guide coordinates your arrival and helps the group meet the driver without unnecessary waiting." to "Rehber varışınızı koordine eder ve gereksiz bekleme olmadan şoförle buluşmanıza yardımcı olur.",
        "The guide keeps the group oriented through the main Umrah stages and coordinates movement when needed." to "Rehber umrenin temel aşamalarında yolunuzu bulmanıza yardımcı olur ve gerektiğinde hareketleri koordine eder.",
        "The holder photo, passport number, name and dates must all fit in the frame." to "Yolcunun fotoğrafı, pasaport numarası, adı ve tarihler kadraja tamamen sığmalıdır.",
        "The hotel is tied to the exact trip nights during calculation. After confirmation and payment, the system starts arranging the selected stay for your dates as part of the same Umrah package." to "Hesaplama sırasında otel, yolculuğunuzun kesin konaklama gecelerine bağlanır. Onay ve ödemeden sonra sistem, seçilen konaklamayı aynı Umre paketi kapsamında tarihleriniz için düzenlemeye başlar.",
        "The journey is built around your dates, budget, hotel level and chosen services. There is no required group of 30–50 strangers — you decide who travels with you." to "Yolculuk tarihleriniz, bütçeniz, otel tercihiniz ve seçtiğiniz hizmetlere göre oluşturulur. Tanımadığınız 30–50 kişiyle seyahat etmek zorunda değilsiniz; kiminle gideceğinize siz karar verirsiniz.",
        "The live package price could not be calculated right now. No estimated supplier price is shown." to "Canlı paket fiyatı şu anda hesaplanamadı. Tahmini tedarikçi fiyatı gösterilmiyor.",
        "The main Economy selection: practical 2★ hotels." to "Ekonomik kategorisindeki temel seçim: kullanışlı 2★ oteller.",
        "The order amount and contents are recorded in the invoice; after payment confirmation you receive payment confirmation and a receipt." to "Sipariş tutarı ve içeriği faturada kayıt altına alınır; ödeme onaylandıktan sonra onay belgesi ve ödeme makbuzu alırsınız.",
        "The outbound flight selection is no longer available. Search flights again." to "Seçtiğiniz gidiş uçuşu artık kullanılamıyor. Uçuşları tekrar arayın.",
        "The package could not be prepared for sharing. Refresh pricing and try again." to "Paket paylaşım için hazırlanamadı. Fiyatları yenileyip tekrar deneyin.",
        "The package could not be prepared for sharing. Refresh the catalogue and try again." to "Paket paylaşım için hazırlanamadı. Kataloğu yenileyip tekrar deneyin.",
        "The package could not be recalculated after your change." to "Seçim değişikliğinden sonra paket yeniden hesaplanamadı.",
        "The package could not be refreshed" to "Paket güncellenemedi",
        "The package currently covers Makkah only" to "Şu anda paket yalnızca Mekke'yi kapsıyor",
        "The package price must be securely confirmed before booking. Please wait a moment and try again." to "Rezervasyon öncesinde paket fiyatı güvenli biçimde doğrulanmalıdır. Biraz bekleyip tekrar deneyin.",
        "The permitted stay is up to 90 days." to "İzin verilen kalış süresi en fazla 90 gündür.",
        "The phone and email here belong to the account owner. Keep them current so access and important trip communication stay with you." to "Buradaki telefon ve e-posta hesap sahibine aittir. Hesap erişimi ve önemli seyahat bildirimleri için güncel tutun.",
        "The pilgrim pays for the trip as one package." to "Umre yolcusu seyahatin ücretini tek bir paket olarak öder.",
        "The profile could not be synced. Your local details remain saved." to "Profil eşitlenemedi. Cihazınızdaki bilgiler kayıtlı kalır.",
        "The provider returned no readable flight options." to "Sağlayıcı okunabilir uçuş seçeneği döndürmedi.",
        "The published flight or current hotel price could not be resolved. Please try again." to "Yayınlanan uçuş veya güncel otel fiyatı doğrulanamadı. Lütfen tekrar deneyin.",
        "The recommended iumrah Family Transfer: more room for your party and luggage with no surcharge." to "Önerilen iumrah Family Transfer: Grubunuz ve valizleriniz için ek ücret ödemeden daha fazla alan.",
        "The request could not be processed." to "İstek işlenemedi.",
        "The request took too long. Please try again." to "İstek çok uzun sürdü. Lütfen tekrar deneyin.",
        "The same vehicle and Haramain choices used inside iumrah Configurator." to "iumrah Configurator'da kullanılan araç ve Haramain seçenekleriyle aynı.",
        "The section is already visible in the booking, but applying Gift Cards and Iumrah Balance is temporarily disabled. We will enable it after the payment flow is ready." to "Bu bölüm rezervasyonda görünür ancak Hediye Kartı ve Iumrah Bakiyesi kullanımı geçici olarak kapalıdır. Ödeme süreci hazır olduğunda etkinleştireceğiz.",
        "The server returned an invalid response." to "Sunucu geçersiz yanıt verdi.",
    )
}
